function App(){const [splash,setSplash]=useState(true),[tab,setTab]=useState('Home'),[page,setPage]=useState('home'),[product,setProduct]=useState(null),[liked,setLiked]=useState(()=>{try{return JSON.parse(localStorage.getItem('tumeni_saved_items')||'[]')}catch{return []}}),[cart,setCart]=useState({}),[checkout,setCheckout]=useState(null),[taskRequest,setTaskRequest]=useState(''),[trackingOrder,setTrackingOrder]=useState(null),[products,setProducts]=useState(fallbackProducts),[profile,setProfile]=useState(null),[searchQuery,setSearchQuery]=useState(''),[categories,setCategories]=useState([]),[paymentNotice,setPaymentNotice]=useState(null);

useEffect(()=>{
  if(!supabaseConfigured)return;
  let mounted=true;

  const applySession=async(session)=>{
    if(!mounted)return;
    if(!session?.user){
      setProfile(null);
      return;
    }

    // Set the signed-in state immediately from the authenticated user.
    // The profile table is loaded afterward for the customer's saved details.
    const user=session.user;
    const metadata=user.user_metadata||{};
    setProfile({
      id:user.id,
      full_name:metadata.full_name||user.email||'Tumeni customer',
      phone:metadata.phone||'',
      email:user.email||'',
      avatar_url:metadata.avatar_url||'',
      role:metadata.account_type==='seller'?'partner':metadata.account_type==='agent'?'agent':'customer'
    });

    const r=await getCurrentProfile();
    if(mounted&&r.data)setProfile(r.data);
  };

  (async()=>{
    const [{data,error},{data:categoryData,error:categoryError}]=await Promise.all([getProducts(),getCategories()]);
    if(mounted){
      if(!error&&data) setProducts(data.map(p=>({...p,img:p.image_url,desc:p.description,category:p.categories?.name||'Other',shop:p.shop_id? p.shops?.name : 'Admin Product'})));
      else if(supabaseConfigured) setProducts([]);
      if(!categoryError&&categoryData) setCategories(categoryData);
    }

    const {data:{session}}=await supabase.auth.getSession();
    await applySession(session);
  })();

  const {data:listener}=supabase.auth.onAuthStateChange((_event,session)=>{
    void applySession(session);
  });

  return()=>{mounted=false;listener?.subscription?.unsubscribe()};
},[]);

useEffect(()=>{
  const params=new URLSearchParams(window.location.search);
  const payment=params.get('payment');

  if(payment==='complete'){
    setPaymentNotice({
      type:'success',
      text:'Payment confirmed by PayChangu. Your order is now paid.'
    });
    setPage('orders');
    setTab('Orders');
  }else if(payment==='failed'){
    setPaymentNotice({
      type:'error',
      text:'PayChangu did not confirm this payment. Your order remains unpaid.'
    });
    setPage('orders');
    setTab('Orders');
  }else if(payment==='verification_pending'){
    setPaymentNotice({
      type:'pending',
      text:'Payment response received. Tumeni is still verifying the payment.'
    });
    setPage('orders');
    setTab('Orders');
  }else if(payment==='error'){
    setPaymentNotice({
      type:'error',
      text:'Tumeni could not complete payment verification. Check your order status before trying again.'
    });
    setPage('orders');
    setTab('Orders');
  }

  if(payment){
    const cleanUrl=window.location.pathname+window.location.hash;
    window.history.replaceState({},document.title,cleanUrl);
  }
},[]);

const goTab=t=>{setTab(t);setProduct(null);setPage(t==='Home'?'home':t==='Explore'?'explore':t==='Orders'?'orders':t==='Profile'?'profile':'favorites')};const runSearch=q=>{setSearchQuery(q);setProduct(null);setTab('Explore');setPage('explore')};const openNotifications=()=>{setProduct(null);setPage('notifications');setTab('Home')};
const toggleLike=id=>setLiked(x=>{const next=x.includes(id)?x.filter(n=>n!==id):[...x,id];try{localStorage.setItem('tumeni_saved_items',JSON.stringify(next))}catch{}return next});
const add=(p,qty=1)=>{setCart(c=>({...c,[p.id]:{product:p,qty:(c[p.id]?.qty||0)+qty}}));};
const cartCount=Object.values(cart).reduce((s,x)=>s+x.qty,0);
if(splash)return <Splash done={()=>setSplash(false)}/>;
let body;
if(page==='home')body=<Home products={products} categories={categories} onProduct={p=>{setProduct(p);setPage('detail')}} liked={liked} toggleLike={toggleLike} setTab={goTab} onRequest={()=>setPage('request')} onSearch={runSearch} onNotifications={openNotifications}/>;
else if(page==='explore')body=<Explore products={products} categories={categories} onProduct={p=>{setProduct(p);setPage('detail')}} liked={liked} toggleLike={toggleLike} searchQuery={searchQuery} onSearch={runSearch}/>;
else if(page==='detail')body=<ProductDetail p={product} products={products} onBack={()=>goTab('Home')} onAdd={add} onViewCart={()=>{setProduct(null);setPage('cart')}} onProduct={p=>setProduct(p)} liked={liked} toggleLike={toggleLike} profile={profile}/>;
else if(page==='cart')body=<Cart cart={cart} setCart={setCart} onCheckout={x=>{setCheckout({...x});setPage('checkout')}} setTab={goTab}/>;
else if(page==='request')body=<RequestTask onBack={()=>goTab('Home')} onQuote={x=>{setTaskRequest(x);setPage('quote')}}/>;
else if(page==='quote')body=<Quote request={taskRequest} onBack={()=>setPage('request')} onPay={total=>{setCheckout({total,task:taskRequest,fees:{serviceFee:3000,deliveryFee:1000,handlingFee:1000}});setPage('checkout')}}/>;
else if(page==='checkout')body=<Checkout {...checkout} onBack={()=>setPage(checkout?.task?'quote':'orders')} onPaid={()=>{setPage('orders');setTab('Orders')}}/>;
else if(page==='orders')body=<Orders notice={paymentNotice} setTab={goTab} onTracking={o=>{setProduct(null);setTrackingOrder(o);setPage('tracking')}} cart={cart} setCart={setCart} onCheckout={x=>{setCheckout({...x});setPage('checkout')}}/>;else if(page==='tracking')body=trackingOrder?<TrackingHistory order={trackingOrder} onBack={()=>setPage('orders')}/>:<SimpleAccountPage title="Tracking unavailable" icon="help" text="Select an order to view its tracking history." onBack={()=>setPage('orders')}/>;
else if(page==='profile')body=<Profile profile={profile} onLogin={()=>setPage('login')} onPayments={()=>setPage('payments')} onSeller={()=>setPage('seller')} onPage={setPage} onLogout={async()=>{await signOut();setProfile(null)}}/>;
else if(page==='login')body=<Login onBack={()=>setPage('profile')} onLogin={async()=>{const r=await getCurrentProfile();setProfile(r.data||null);setPage('profile')}}/>;
else if(page==='payments')body=<PaymentMethods onBack={()=>setPage('profile')}/>;
else if(['edit-profile','addresses','notifications','requests','settings','security','help'].includes(page))body=<AccountPage type={page} profile={profile} onBack={()=>setPage('profile')} onSave={async data=>{if(!supabase||!profile?.id)return;const {data:updated,error}=await supabase.from('profiles').update(data).eq('id',profile.id).select().single();if(error)throw error;setProfile(updated)}}/>;
else if(page==='agent')body=profile?.role==='agent'?<AgentDashboard profile={profile} onBack={()=>setPage('profile')}/>:<SimpleAccountPage title="Access denied" icon="help" text="Agent access is only available to internal delivery employees." onBack={()=>setPage('profile')}/>;else if(page==='admin-agents')body=profile?.role==='admin'?<AdminEmployees onBack={()=>setPage('profile')}/>:<SimpleAccountPage title="Access denied" icon="help" text="Administrator access is required." onBack={()=>setPage('profile')}/>;else if(page==='seller')body=(profile?.role==='partner'||profile?.role==='admin')?<SellerDashboard profile={profile} onBack={()=>setPage('profile')}/>:<SimpleAccountPage title="Access denied" icon="help" text="Seller access is only available to partner and admin accounts." onBack={()=>setPage('profile')}/>;else if(page==='admin-categories')body=profile?.role==='admin'?<AdminCategories onBack={()=>setPage('profile')}/>:<SimpleAccountPage title="Access denied" icon="help" text="Administrator access is required." onBack={()=>setPage('profile')}/>;
else body=<div className="screen content"><Header title="Favorites"/><div className="grid">{products.filter(p=>liked.includes(p.id)).map(p=><ProductCard key={p.id} p={p} liked={true} toggleLike={toggleLike} onClick={()=>{setProduct(p);setPage('detail')}}/>)}</div></div>;
return <div className="page"><main className="phone">{body}{!['detail','checkout','login','payments','request','quote','seller','agent','admin-agents','admin-categories'].includes(page)&&<BottomNav tab={tab} onTab={goTab} count={cartCount}/>}</main></div>}
createRoot(document.getElementById('root')).render(<App/>);
